```javascript
let stdin = "";
process.stdin.setEncoding("utf8");
for await (const chunk of process.stdin) {
  stdin += chunk;
}

const input = JSON.parse(stdin);
if (input.stop_hook_active !== true) {
  console.log(
    JSON.stringify({
      decision: "block",
      reason: "Minimal Stop hook continuation reproduction.",
    }),
